import React, { useEffect, useState } from 'react';

const lines = [
  'name = "Chetanya Makkar"',
  'major = "Computer Science"',
  'minor = "Computational Finance"',
  'gpa = 3.76',
  'school = "University of Maryland"'
];

export default function App() {
  const [visibleLines, setVisibleLines] = useState([]);

  useEffect(() => {
    let i = 0;
    const interval = setInterval(() => {
      setVisibleLines((prev) => [...prev, lines[i]]);
      i++;
      if (i === lines.length) clearInterval(interval);
    }, 1000); // delay between lines
    return () => clearInterval(interval);
  }, []);

  return (
    <div className="bg-black text-green-400 min-h-screen flex items-center justify-center font-mono text-xl p-6">
      <div className="space-y-2 text-left">
        {visibleLines.map((line, idx) => (
          <div key={idx} className="whitespace-nowrap border-r-2 border-green-400 animate-typing overflow-hidden w-fit">
            {line}
          </div>
        ))}
      </div>
    </div>
  );
}
